import { privateJson } from './session.js';
import { mountCoaching } from './coaching.js';
import { mountProgress } from './progress.js';
const root=document.querySelector('#training-root'),params=new URLSearchParams(location.search);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nf=new Intl.NumberFormat('en-AU',{maximumFractionDigits:2});
const distance=v=>Number.isFinite(v)?(v<1000?nf.format(v)+' m':nf.format(v/1000)+' km'):'—';
const time=v=>{if(!Number.isFinite(v))return '—';const n=Math.round(v);return n>=3600?Math.floor(n/3600)+'h '+Math.floor(n%3600/60)+'m':Math.floor(n/60)+':'+String(n%60).padStart(2,'0');};
const pace=v=>Number.isFinite(v)?time(v):'—';
const date=v=>new Date(v+'T12:00Z').toLocaleDateString('en-AU',{day:'numeric',month:'short',timeZone:'UTC'});
const arrow='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg>';
const logo='<svg viewBox="0 0 32 32" aria-hidden="true"><path d="M3 25 11 7h5L8 25m9 0 8-18h4l-8 18"/></svg>';
const detail=s=>'/app.html?activity='+encodeURIComponent(s.id);
let data,view=['progress','sessions'].includes(params.get('view'))?params.get('view'):location.hash==='#progress'?'progress':'today',windowChoice=params.get('window')==='all'?'all':'90',type='all',shown=12,busy=false,motion=true;
try{motion=localStorage.getItem('mfa-visual-motion')!=='off';}catch{}
const reduced=matchMedia('(prefers-reduced-motion:reduce)');
function url(next){return next==='today'?'/training':'/training?view='+next;}
function rows(sessions){return sessions.map(s=>`<a class="td-session" href="${detail(s)}"><span class="td-date">${date(s.date)}</span><span class="td-session-name"><strong>${esc(s.title)}</strong><small>${esc(s.source)}${s.environment==='indoor'?' · Indoor':''}</small></span><span><strong>${distance(s.distanceM)}</strong><small>${time(s.durationS)}</small></span><span class="td-pace">${pace(s.paceSPerKm)}${s.paceSPerKm===null?'':' <small>/km</small>'}</span>${arrow}</a>`).join('');}
function latest(){const s=data.sessions.find(s=>s.run)||data.sessions[0];if(!s)return `<section class="td-latest td-empty"><h2>Your first run starts the story.</h2><p>Connect Garmin or bring a recording. Your coach and progress will build from there.</p><a class="primary-button" href="/account">Add your first activity ${arrow}</a></section>`;
return `<section class="td-latest" aria-labelledby="latest-title"><div class="td-section-top"><h2 id="latest-title">Latest run</h2><span>${date(s.date)}</span></div><a class="td-latest-title" href="${detail(s)}"><h3>${esc(s.title)}</h3>${arrow}</a><dl class="td-latest-metrics"><div><dt>Time</dt><dd>${time(s.durationS)}</dd></div>${s.paceSPerKm!==null?`<div><dt>Distance</dt><dd>${distance(s.distanceM)}</dd></div><div><dt>Pace /km</dt><dd>${pace(s.paceSPerKm)}</dd></div>`:s.hrBpm!==null?`<div><dt>Average heart rate</dt><dd>${Math.round(s.hrBpm)} <small>bpm</small></dd></div>`:''}</dl><div class="td-latest-actions"><a class="${s.checkinComplete?'secondary-button':'primary-button'}" href="${detail(s)}${s.checkinComplete?'':'#checkin'}">${s.checkinComplete?'Explore this run':'Log how it felt'} ${arrow}</a>${!s.checkinComplete?`<a class="text-button" href="${detail(s)}#session-details">View analysis ${arrow}</a>`:''}</div></section>`;}
function week(){const start=new Date(data.anchor+'T12:00Z');start.setUTCDate(start.getUTCDate()-6);const key=start.toISOString().slice(0,10),runs=data.sessions.filter(s=>s.run&&s.date>=key),metres=runs.reduce((n,s)=>n+(s.distanceM??0),0),seconds=runs.reduce((n,s)=>n+(s.durationS??0),0);return `<section class="td-week" aria-labelledby="week-title"><div class="td-section-top"><h2 id="week-title">Last 7 days</h2><a href="${url('progress')}">See progress ${arrow}</a></div><dl><div><dt>Runs</dt><dd>${runs.length}</dd></div><div><dt>Distance</dt><dd>${distance(metres)}</dd></div><div><dt>Time running</dt><dd>${time(seconds)}</dd></div></dl></section>`;}
function sessions(){const selected=data.sessions.filter(s=>type==='all'||(type==='run'?s.run:!s.run));return `<section class="td-all-sessions" aria-labelledby="sessions-title"><div class="td-section-top"><div><h1 id="sessions-title">Your sessions.</h1><p>${selected.length} activities</p></div><a class="secondary-button" href="/account">Add an activity ${arrow}</a></div><div class="td-session-tools"><div class="tr-window" role="group" aria-label="Session type">${[['all','All'],['run','Running'],['walk','Walking']].map(([key,label])=>`<button data-type="${key}" aria-pressed="${type===key}">${label}</button>`).join('')}</div>${windows()}</div><div class="td-session-list">${rows(selected.slice(0,shown))||'<div class="td-empty"><h2>No sessions here yet.</h2><p>Choose another filter or add an activity from Account.</p></div>'}</div>${selected.length>shown?'<button class="secondary-button" id="more-sessions">Show more sessions</button>':''}</section>`;}
function windows(){return `<div class="tr-window" role="group" aria-label="History window">${[['90','90 days'],['all','All history']].map(([key,label])=>`<button data-window="${key}" aria-pressed="${windowChoice===key}">${label}</button>`).join('')}</div>`;}
function render(){document.title=(view==='progress'?'Progress':view==='sessions'?'Sessions':'Training')+' — My Fitness Analyser';params.set('view',view);params.set('window',windowChoice);history.replaceState(null,'','/training?'+params);root.innerHTML=`<header class="tr-header"><a class="tr-brand" href="/training" aria-label="My Fitness Analyser training">${logo}<span>My Fitness<br><strong>Analyser</strong></span></a><nav aria-label="Main"><a href="/training" ${view!=='progress'?'aria-current="page"':''}>Training</a><a href="/training?view=progress" ${view==='progress'?'aria-current="page"':''}>Progress</a><a href="/journal">Journal</a><a href="/account">Account</a></nav><button class="tr-motion" id="motion" aria-label="Toggle motion effects" aria-pressed="${motion&&!reduced.matches}">Motion <span>${motion&&!reduced.matches?'on':'off'}</span></button></header><main id="training-main" class="td-main" data-view="${view}">${view==='today'?`<div class="td-page-heading"><div><h1>Make the next run count.</h1><p>${new Date(data.anchor+'T12:00Z').toLocaleDateString('en-AU',{weekday:'long',day:'numeric',month:'long',timeZone:'UTC'})}${data.dataset==='synthetic'?' · Synthetic design preview':''}</p></div><a class="secondary-button" href="/journal#quick-log">Log your weight ${arrow}</a></div><div class="td-home-grid"><section class="td-coach" id="home-coach" aria-label="Your coaching brief"></section><aside>${latest()}${week()}</aside></div><section class="td-recent" aria-labelledby="recent-title"><div class="td-section-top"><h2 id="recent-title">Recent sessions</h2><a href="${url('sessions')}">All sessions ${arrow}</a></div><div class="td-session-list">${rows(data.sessions.slice(0,4))||'<p>Your sessions will appear here.</p>'}</div></section>`:view==='sessions'?sessions():`<div class="td-page-heading"><div><h1>Your work, taking shape.</h1><p>See what is building. Choose a month or a run to go deeper.</p></div>${windows()}</div><section id="progress" class="pr-section" aria-label="Training progress"></section><details class="td-record-details"><summary>Sources and calculations</summary><p>Your Garmin recordings and accepted Nike Run Club or Strava screenshots stay linked to their original records. Charts use the measurements available in each source.</p><a href="/account">Manage your sources ${arrow}</a></details>`}<footer class="td-footer"><a href="/account">Connections & settings</a><span id="sync-status" role="status"></span>${data.local||data.garminConfigured?'<button class="text-button" id="sync">Sync Garmin</button>':''}</footer></main><p class="td-notice" id="notice" role="status"></p>`;
 if(view==='progress')mountProgress(document.querySelector('#progress'),data);
 if(view==='today'){const target=document.querySelector('#home-coach');if(data.cloud)void mountCoaching(target);else target.innerHTML='<div class="td-preview"><h2>Your coaching brief</h2><p>This design preview uses synthetic records. Your signed-in app reads your own training.</p><a href="/account">Open your account</a></div>';}
 bind();
}
function bind(){document.querySelectorAll('[data-window]').forEach(b=>b.addEventListener('click',async()=>{if(b.getAttribute('aria-pressed')==='true'||busy)return;busy=true;document.querySelectorAll('[data-window]').forEach(b=>b.disabled=true);try{await load(b.dataset.window);document.querySelector(`[data-window="${windowChoice}"]`)?.focus({preventScroll:true});}catch(e){document.querySelector('#notice').textContent=e.message;document.querySelectorAll('[data-window]').forEach(b=>b.disabled=false);}finally{busy=false;}}));
 document.querySelectorAll('[data-type]').forEach(b=>b.addEventListener('click',()=>{type=b.dataset.type;shown=12;render();document.querySelector(`[data-type="${type}"]`).focus({preventScroll:true});}));document.querySelector('#more-sessions')?.addEventListener('click',()=>{shown+=12;render();document.querySelector('.td-session-list')?.scrollIntoView({block:'nearest'});});
 document.querySelector('#motion').addEventListener('click',()=>{motion=!motion;try{localStorage.setItem('mfa-visual-motion',motion?'on':'off');}catch{}document.querySelector('#motion').setAttribute('aria-pressed',String(motion&&!reduced.matches));document.querySelector('#motion span').textContent=motion&&!reduced.matches?'on':'off';});
 document.querySelector('#sync')?.addEventListener('click',async e=>{const b=e.currentTarget;b.disabled=true;document.querySelector('#sync-status').textContent='Syncing your recordings…';try{const result=await privateJson('/api/garmin/sync',{method:'POST'});await load(windowChoice);document.querySelector('#sync-status').textContent=`${result.imported||0} added · ${result.updated||0} updated`;}catch(e){b.disabled=false;document.querySelector('#sync-status').textContent=e.message;}});
}
async function load(choice=windowChoice){data=await privateJson('/api/training?window='+choice);windowChoice=choice;render();}
reduced.addEventListener('change',()=>{const b=document.querySelector('#motion');if(b){b.setAttribute('aria-pressed',String(motion&&!reduced.matches));b.querySelector('span').textContent=motion&&!reduced.matches?'on':'off';}});
try{await load();}catch(e){root.innerHTML=`<main class="training-loading"><h1>Your training couldn’t load.</h1><p>${esc(e.message)}</p><button class="primary-button" id="retry">Try again</button></main>`;document.querySelector('#retry').addEventListener('click',()=>location.reload());}
